export default "import { CustomTransformOperator, DataFrame, FieldType } from '@grafana/data';\nimport { Observable, map } from 'rxjs';\nimport {\n  EmbeddedScene,\n  PanelBuilders,\n  SceneAppPage,\n  SceneAppPageState,\n  SceneDataTransformer,\n  SceneFlexItem,\n  SceneFlexLayout,\n} from '@grafana/scenes';\nimport { getEmbeddedSceneDefaults, getQueryRunnerWithRandomWalkQuery } from './utils';\n\nexport function getTransformationsTest(defaults: SceneAppPageState) {\n  return new SceneAppPage({\n    ...defaults,\n    getScene: () => {\n      return new EmbeddedScene({\n        ...getEmbeddedSceneDefaults(),\n        $data: getQueryRunnerWithRandomWalkQuery({\n          scenarioId: 'csv_metric_values',\n          stringInput: '1,20,90,30,5,0',\n        }),\n        body: new SceneFlexLayout({\n          direction: 'row',\n          children: [\n            new SceneFlexItem({\n              body: new SceneFlexLayout({\n                direction: 'column',\n                children: [\n                  new SceneFlexItem({\n                    body: new SceneFlexLayout({\n                      direction: 'row',\n                      children: [\n                        new SceneFlexItem({\n                          body: PanelBuilders.timeseries().setTitle('Source data (global query)').build(),\n                        }),\n                        new SceneFlexItem({\n                          body: PanelBuilders.stat()\n                            .setTitle('Transformed data')\n                            .setData(\n                              new SceneDataTransformer({\n                                transformations: [\n                                  {\n                                    id: 'reduce',\n                                    options: {\n                                      reducers: ['last', 'mean'],\n                                    },\n                                  },\n                                ],\n                              })\n                            )\n                            .build(),\n                        }),\n                        new SceneFlexItem({\n                          body: PanelBuilders.timeseries()\n                            .setTitle('Custom transformer (log10 scale)')\n                            .setData(\n                              new SceneDataTransformer({\n                                transformations: [log10Transform()],\n                              })\n                            )\n                            .build(),\n                        }),\n                        new SceneFlexItem({\n                          body: PanelBuilders.timeseries()\n                            .setTitle('Custom transformer (log10 scale) that throws')\n                            .setData(\n                              new SceneDataTransformer({\n                                transformations: [log10Transform(true)],\n                              })\n                            )\n                            .build(),\n                        }),\n                      ],\n                    }),\n                  }),\n                  new SceneFlexItem({\n                    body: PanelBuilders.stat()\n                      .setTitle('Query with predefined transformations')\n                      .setData(\n                        new SceneDataTransformer({\n                          $data: getQueryRunnerWithRandomWalkQuery(),\n                          transformations: [\n                            {\n                              id: 'reduce',\n                              options: {\n                                reducers: ['mean'],\n                              },\n                            },\n                          ],\n                        })\n                      )\n                      .build(),\n                  }),\n                  new SceneFlexItem({\n                    body: PanelBuilders.stat()\n                      .setTitle('Datasoure and transformations error')\n                      .setData(\n                        new SceneDataTransformer({\n                          $data: getQueryRunnerWithRandomWalkQuery({ datasource: { uid: 'nonexistent' } }),\n                          transformations: [log10Transform(true)],\n                        })\n                      )\n                      .build(),\n                  }),\n                ],\n              }),\n            }),\n          ],\n        }),\n      });\n    },\n  });\n}\n\nconst log10Transform: (shouldThrow?: boolean) => CustomTransformOperator =\n  (shouldThrow = false) =>\n  () =>\n  (source: Observable<DataFrame[]>) => {\n    return source.pipe(\n      map((data: DataFrame[]) => {\n        return data.map((frame) => {\n          if (shouldThrow) {\n            data[1999].fields = [];\n          }\n\n          return {\n            ...frame,\n            fields: frame.fields.map((field) => {\n              if (field.type === FieldType.number) {\n                return {\n                  ...field,\n                  values: field.values.map((v) => Math.log(v) / Math.log(10)),\n                };\n              }\n\n              return field;\n            }),\n          };\n        });\n      })\n    );\n  };\n";